<?php
declare(strict_types=1);

function physical_store_v14(array $tenant):bool{return (bool)($tenant['physical_store_enabled']??0);}
function physical_branch_v14(App $app,array $tenant):array
{
    $id=(int)($_REQUEST['branch_id']??($_SESSION['physical_branch'][(int)$tenant['id']]??0));
    return $app->cached('physical-branch:'.(int)$tenant['id'].':'.$id, function () use ($app, $tenant, $id) {
        $branch=$id?$app->one('SELECT * FROM branches WHERE id=? AND tenant_id=? AND is_active=1',[$id,$tenant['id']]):null;
        if ($branch && !empty($_REQUEST['branch_id'])) session_change176(function () use ($tenant, $id) { $_SESSION['physical_branch'][(int)$tenant['id']]=$id; });
        return $branch?:($app->one('SELECT * FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,id LIMIT 1',[$tenant['id']])?:[]);
    });
}
function physical_number_v14(string $prefix):string{return $prefix.'-'.date('ymd-His').'-'.strtoupper(bin2hex(random_bytes(2)));}
function stock_change_v14(App $app,int $tenantId,int $branchId,int $productId,float $delta,string $type,string $referenceType,?int $referenceId,?int $userId,string $notes='',float $unitCost=0):void
{
    if(!is_finite($delta)||!is_finite($unitCost))throw new DomainException('Cantidad o costo inválido.');
    $own=!$app->db->inTransaction();if($own)$app->db->beginTransaction();
    try{if(function_exists('r2_stock_product') && r2_stock_product($app,$tenantId,$branchId,$productId,$delta,$type,$referenceType,$referenceId,$userId,$notes,$unitCost)){if($own)$app->db->commit();return;}stock_change_locked_qa($app,$tenantId,$branchId,$productId,$delta,$type,$referenceType,$referenceId,$userId,$notes,$unitCost);if($own)$app->db->commit();}
    catch(Throwable $e){if($own&&$app->db->inTransaction())$app->db->rollBack();throw $e;}
}
function stock_change_locked_qa(App $app,int $tenantId,int $branchId,int $productId,float $delta,string $type,string $referenceType,?int $referenceId,?int $userId,string $notes='',float $unitCost=0):void
{
    if(!$app->one('SELECT id FROM products WHERE id=? AND tenant_id=?',[$productId,$tenantId])||!$app->one('SELECT id FROM branches WHERE id=? AND tenant_id=?',[$branchId,$tenantId]))throw new DomainException('Producto o sucursal no pertenece a la empresa.');
    $app->exec('INSERT INTO product_inventory(tenant_id,branch_id,product_id,quantity,last_cost) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE updated_at=NOW()',[$tenantId,$branchId,$productId,0,$unitCost]);
    $row=$app->one('SELECT * FROM product_inventory WHERE tenant_id=? AND branch_id=? AND product_id=? FOR UPDATE',[$tenantId,$branchId,$productId]);$before=(float)$row['quantity'];$after=$before+$delta;
    if($after<0&&!(int)$row['allow_negative'])throw new DomainException('Existencia insuficiente para '.$notes.'. Disponible: '.rtrim(rtrim(number_format($before,3,'.',''),'0'),'.'));
    $average=(float)$row['avg_cost'];if($delta>0&&$unitCost>0&&$after>0)$average=((max(0,$before)*$average)+($delta*$unitCost))/(max(0,$before)+$delta);
    $app->exec('UPDATE product_inventory SET quantity=?,last_cost=IF(?>0,?,last_cost),avg_cost=? WHERE id=?',[$after,$unitCost,$unitCost,$average,$row['id']]);
    $app->exec('INSERT INTO inventory_movements(tenant_id,branch_id,product_id,movement_type,quantity,before_quantity,after_quantity,unit_cost,reference_type,reference_id,notes,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$tenantId,$branchId,$productId,$type,$delta,$before,$after,$unitCost,$referenceType,$referenceId,$notes,$userId]);
}

function inventory_take_order_v14(App $app,int $orderId):void
{
    $order=$app->one('SELECT o.*,t.physical_store_enabled FROM orders o JOIN tenants t ON t.id=o.tenant_id WHERE o.id=?',[$orderId]);if(!$order||empty($order['branch_id']))return;if($app->one('SELECT id FROM inventory_movements WHERE reference_type="online_order" AND reference_id=? LIMIT 1',[$orderId]))return;
    foreach($app->all('SELECT oi.product_id,oi.quantity,p.name,p.cost,p.track_inventory FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY p.id',[$orderId]) as $item)if((int)$item['track_inventory'])stock_change_v14($app,(int)$order['tenant_id'],(int)$order['branch_id'],(int)$item['product_id'],-(float)$item['quantity'],'online_sale','online_order',$orderId,null,'Pedido web #'.$order['order_number'].' · '.$item['name'],(float)$item['cost']);
}

function inventory_restore_order_v14(App $app,int $orderId,?int $userId=null):void
{
    if(function_exists('r3_active')&&r3_active($app))r3_gift_refund_order($app,$orderId);
    if($app->one('SELECT id FROM inventory_movements WHERE reference_type="order_cancel" AND reference_id=? LIMIT 1',[$orderId]))return;$order=$app->one('SELECT * FROM orders WHERE id=?',[$orderId]);if(!$order||empty($order['branch_id']))return;
    foreach($app->all('SELECT product_id,ABS(SUM(quantity)) quantity,MAX(unit_cost) unit_cost FROM inventory_movements WHERE reference_type="online_order" AND reference_id=? GROUP BY product_id',[$orderId]) as $move)stock_change_v14($app,(int)$order['tenant_id'],(int)$order['branch_id'],(int)$move['product_id'],(float)$move['quantity'],'return','order_cancel',$orderId,$userId,'Devolución por cancelación #'.$order['order_number'],(float)$move['unit_cost']);
}

function tenant_products_v14(App $app,array $user,array $tenant):void
{
    $physical=physical_store_v14($tenant);$branches=$app->all('SELECT * FROM branches WHERE tenant_id=? AND is_active=1 ORDER BY is_default DESC,name',[$tenant['id']]);$branch=physical_branch_v14($app,$tenant);
    if(is_post()){verify_csrf();try{$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));if(!$physical&&$id)$_POST['supplier_id']=$app->one('SELECT supplier_id FROM products WHERE id=? AND tenant_id=?',[$id,$tenant['id']])['supplier_id']??null;if($id&&!$app->one('SELECT id FROM products WHERE id=? AND tenant_id=?',[$id,$tenant['id']]))throw new DomainException('Producto no disponible para esta empresa.');if($name==='')throw new RuntimeException('Escribe el nombre del producto.');foreach(['category_id'=>'categories','supplier_id'=>'suppliers'] as $field=>$table)if(!empty($_POST[$field])&&!$app->one("SELECT id FROM $table WHERE id=? AND tenant_id=?",[(int)$_POST[$field],$tenant['id']]))throw new DomainException('Categoría o proveedor no pertenece a esta empresa.');$sku=trim((string)($_POST['sku']??''));if($sku!==''&&$app->one('SELECT id FROM products WHERE tenant_id=? AND sku=? AND id<>?',[$tenant['id'],$sku,$id]))throw new RuntimeException('El código o SKU ya está usado.');$price=(float)($_POST['price']??0);$salePrice=($_POST['sale_price']??'')!==''?(float)$_POST['sale_price']:null;$taxRate=(float)($_POST['tax_rate']??0);$minQty=(float)($_POST['min_qty']??1);$qtyStep=(float)($_POST['qty_step']??1);$decimals=(int)($_POST['decimals']??0);$cost=($_POST['cost']??'')!==''?(float)$_POST['cost']:0;$initialStock=(float)($_POST['initial_stock']??0);foreach([$price,$salePrice,$taxRate,$minQty,$qtyStep,$cost,$initialStock] as $amount)if($amount!==null&&(!is_finite((float)$amount)||(float)$amount<0))throw new RuntimeException('Precio, impuesto, costo y existencias deben ser valores no negativos.');if($minQty<=0||$qtyStep<=0||$decimals<0||$decimals>6)throw new RuntimeException('Revisa la unidad mínima y el paso de cantidad.');foreach([$minQty,$qtyStep,$initialStock] as $quantity)if(abs($quantity*1000-round($quantity*1000))>.000001)throw new RuntimeException('La cantidad mínima, el incremento y la existencia admiten hasta 3 decimales.');$image=upload_image('image');$values=[$name,slugify((string)(($_POST['slug']??'')?:$name)),($_POST['category_id']??'')?(int)$_POST['category_id']:null,$sku,trim((string)($_POST['description']??'')),trim((string)($_POST['characteristics']??'')),$price,$salePrice,$taxRate,trim((string)($_POST['unit_label']??'unidad')),$minQty,$qtyStep,$decimals,trim((string)($_POST['badge']??'')),in_array($_POST['status']??'active',['active','hidden','sold_out'],true)?$_POST['status']:'active',($_POST['supplier_id']??'')?(int)$_POST['supplier_id']:null,$cost,isset($_POST['track_inventory'])?1:0];
        $app->db->beginTransaction();if($id){$sql='UPDATE products SET name=?,slug=?,category_id=?,sku=?,description=?,characteristics=?,price=?,sale_price=?,tax_rate=?,unit_label=?,min_qty=?,qty_step=?,decimals=?,badge=?,status=?,supplier_id=?,cost=?,track_inventory=?'.($image?',image=?':'').' WHERE id=? AND tenant_id=?';if($image)$values[]=$image;$values[]=$id;$values[]=$tenant['id'];$app->exec($sql,$values);}else{$app->exec('INSERT INTO products(tenant_id,name,slug,category_id,sku,description,characteristics,price,sale_price,tax_rate,unit_label,min_qty,qty_step,decimals,badge,status,supplier_id,cost,track_inventory,image) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',array_merge([$tenant['id']],$values,[$image]));$id=(int)$app->db->lastInsertId();}
        if(!empty($branch)){ $app->exec('INSERT INTO product_inventory(tenant_id,branch_id,product_id,track_stock,quantity,min_stock,reorder_point,last_cost,allow_negative) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE track_stock=VALUES(track_stock),min_stock=VALUES(min_stock),reorder_point=VALUES(reorder_point),last_cost=VALUES(last_cost),allow_negative=VALUES(allow_negative)',[$tenant['id'],$branch['id'],$id,isset($_POST['track_inventory'])?1:0,$initialStock,(float)($_POST['min_stock']??0),(float)($_POST['reorder_point']??0),$cost,isset($_POST['allow_negative'])?1:0]);}
        $app->db->commit();audit($app,$tenant['id'],$user['id'],'save_product','product',$id);flash('success','Producto e inventario guardados.');}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/productos'.(!empty($branch)?'?branch_id='.(int)$branch['id']:'')));}
    $edit=!empty($_GET['edit'])?$app->one('SELECT * FROM products WHERE id=? AND tenant_id=?',[(int)$_GET['edit'],$tenant['id']]):null;$cats=$app->all('SELECT * FROM categories WHERE tenant_id=? ORDER BY name',[$tenant['id']]);$suppliers=$physical?$app->all('SELECT * FROM suppliers WHERE tenant_id=? AND is_active=1 ORDER BY name',[$tenant['id']]):[];
    $where=['p.tenant_id=?'];$params=[$tenant['id']];$q=trim((string)($_GET['q']??''));if($q!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR p.description LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if(!empty($_GET['category_id'])){$where[]='p.category_id=?';$params[]=(int)$_GET['category_id'];}if($physical&&!empty($_GET['supplier_id'])){$where[]='p.supplier_id=?';$params[]=(int)$_GET['supplier_id'];}if(!empty($_GET['status'])){$where[]='p.status=?';$params[]=$_GET['status'];}if(($_GET['stock']??'')==='low')$where[]='COALESCE(i.quantity,0)<=COALESCE(NULLIF(i.reorder_point,0),i.min_stock)';elseif(($_GET['stock']??'')==='available')$where[]='COALESCE(i.quantity,0)>0';elseif(($_GET['stock']??'')==='zero')$where[]='COALESCE(i.quantity,0)<=0';
