    echo '<form class="card admin-card filter-bar" method="get"><div class="grid grid-4">'.field('Nombre o código','q',$q).'<div class="form-group"><label>Categoría</label><select class="input" name="category_id"><option value="">Todas</option>';foreach($cats as $c)echo '<option value="'.(int)$c['id'].'" '.(((int)($_GET['category_id']??0)===(int)$c['id'])?'selected':'').'>'.e($c['name']).'</option>';echo '</select></div><div class="form-group"><label>Estado</label><select class="input" name="status"><option value="">Todos</option>';foreach(['active'=>'Activo','hidden'=>'Oculto','sold_out'=>'Agotado'] as $key=>$label)echo '<option value="'.$key.'" '.(($_GET['status']??'')===$key?'selected':'').'>'.$label.'</option>';echo '</select></div>';if($physical){echo '<div class="form-group"><label>Proveedor</label><select class="input" name="supplier_id"><option value="">Todos</option>';foreach($suppliers as $s)echo '<option value="'.(int)$s['id'].'" '.(((int)($_GET['supplier_id']??0)===(int)$s['id'])?'selected':'').'>'.e($s['name']).'</option>';echo '</select></div>';} {echo '<div class="form-group"><label>Existencias</label><select class="input" name="stock"><option value="">Todas</option><option value="available" '.(($_GET['stock']??'')==='available'?'selected':'').'>Disponibles</option><option value="low" '.(($_GET['stock']??'')==='low'?'selected':'').'>Bajo mínimo</option><option value="zero" '.(($_GET['stock']??'')==='zero'?'selected':'').'>Agotadas</option></select></div>';}echo '</div><button class="btn">Aplicar filtros</button> <a class="btn btn-light" href="'.url('admin/productos').'">Limpiar</a></form>';
