function tenant_inventory_v14(App $app,array $user,array $tenant):void
{
    $branch=physical_branch_v14($app,$tenant);if(!$branch)throw new RuntimeException('Crea una sucursal antes de administrar inventario.');if(is_post()){verify_csrf();try{$productId=(int)$_POST['product_id'];$qty=abs((float)$_POST['quantity']);$direction=($_POST['direction']??'in')==='out'?-1:1;$app->db->beginTransaction();stock_change_v14($app,(int)$tenant['id'],(int)$branch['id'],$productId,$qty*$direction,'adjustment','manual',null,(int)$user['id'],trim((string)($_POST['notes']??'Ajuste manual')),(float)($_POST['unit_cost']??0));$app->db->commit();flash('success','Ajuste registrado en el kardex.');}catch(Throwable $e){if($app->db->inTransaction())$app->db->rollBack();flash('error',$e->getMessage());}redirect(url('admin/inventario?branch_id='.(int)$branch['id']));}
    $products=$app->all('SELECT p.id,p.name,p.sku,COALESCE(i.quantity,0) quantity,COALESCE(i.reserved_quantity,0) reserved,COALESCE(i.reorder_point,0) reorder_point,COALESCE(i.avg_cost,p.cost,0) avg_cost FROM products p LEFT JOIN product_inventory i ON i.product_id=p.id AND i.branch_id=? WHERE p.tenant_id=? ORDER BY p.name',[$branch['id'],$tenant['id']]);$moves=$app->all('SELECT m.*,p.name product_name,u.name user_name FROM inventory_movements m JOIN products p ON p.id=m.product_id LEFT JOIN users u ON u.id=m.user_id WHERE m.tenant_id=? AND m.branch_id=? ORDER BY m.created_at DESC LIMIT 100',[$tenant['id'],$branch['id']]);admin_shell_start('Inventario y kardex',$user,$tenant,'inventario');echo '<div class="split"><form class="card admin-card" method="post">'.csrf_field().'<h2>Ajuste de existencia</h2><input type="hidden" name="branch_id" value="'.(int)$branch['id'].'"><div class="form-group"><label>Producto</label><select class="input" name="product_id">';foreach($products as $p)echo '<option value="'.(int)$p['id'].'">'.e($p['name'].' · '.$p['sku']).'</option>';echo '</select></div><div class="split"><div class="form-group"><label>Movimiento</label><select class="input" name="direction"><option value="in">Entrada</option><option value="out">Salida</option></select></div>'.field('Cantidad','quantity',1,true,'number','0.001').'</div>'.field('Costo unitario','unit_cost',0,false,'number','0.01').field('Motivo / documento','notes','Ajuste manual',true).'<button class="btn btn-block">Registrar ajuste</button></form><section class="card admin-card"><h2>Existencias · '.e($branch['name']).'</h2><div class="table-wrap"><table class="table"><tr><th>Producto</th><th>Disponible</th><th>Reservado</th><th>Mínimo</th><th>Costo prom.</th></tr>';foreach($products as $p)echo '<tr><td>'.e($p['name']).'<br><small>'.e($p['sku']).'</small></td><td><span class="status '.((float)$p['quantity']<=(float)$p['reorder_point']?'status-off':'').'">'.e($p['quantity']).'</span></td><td>'.e($p['reserved']).'</td><td>'.e($p['reorder_point']).'</td><td>'.money((float)$p['avg_cost']).'</td></tr>';echo '</table></div></section></div><section class="card admin-card" style="margin-top:20px"><h2>Kardex reciente</h2><div class="table-wrap"><table class="table"><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th><th>Antes → después</th><th>Detalle</th></tr>';foreach($moves as $m)echo '<tr><td>'.e(date('d/m/Y H:i',strtotime($m['created_at']))).'</td><td>'.e($m['product_name']).'</td><td>'.e($m['movement_type']).'</td><td>'.e($m['quantity']).'</td><td>'.e($m['before_quantity'].' → '.$m['after_quantity']).'</td><td>'.e($m['notes']).'</td></tr>';echo '</table></div></section>';admin_shell_end();
}

function tenant_pos_v14(App $app,array $user,array $tenant):void
