        'purchases'=>['compras',['date'=>'Fecha','number'=>'Compra','invoice'=>'Factura','supplier'=>'Proveedor','total'=>'Total','balance'=>'Saldo','status'=>'Estado'],'SELECT purchase_date date,purchase_number number,invoice_number invoice,s.name supplier,p.total,p.balance,p.payment_status status FROM purchases p JOIN suppliers s ON s.id=p.supplier_id WHERE p.tenant_id=? AND p.purchase_date BETWEEN ? AND ?'],
