        'cxp'=>['cuentas-por-pagar',['document'=>'Documento','supplier'=>'Proveedor','issue'=>'Emisión','due'=>'Vence','amount'=>'Monto','balance'=>'Saldo','status'=>'Estado'],'SELECT a.document_number document,s.name supplier,a.issue_date issue,a.due_date due,a.amount,a.balance,a.status FROM accounts_payable a JOIN suppliers s ON s.id=a.supplier_id WHERE a.tenant_id=?']];if(!isset($definitions[$type]))throw new RuntimeException('Exportación no válida.');[$file,$available,$sql]=$definitions[$type];$period=in_array($type,['sales','items','purchases'],true);$params=$period?[$tenant['id'],$from,$to,...(in_array($type,['sales','items'],true)?[$tenant['id'],$from,$to]:[])]:[$tenant['id']];$rows=$app->all($sql,$params);$selected=$columns?array_values(array_intersect(array_keys($available),array_map('strval',$columns))):array_keys($available);if(!$selected)$selected=array_keys($available);$out=[];foreach($rows as $row){$line=[];foreach($selected as $key)$line[$key]=$row[$key]??'';$out[]=$line;}csv_download_v1('fisitapp-'.$file.'-'.$from.'-'.$to.'.csv',array_map(fn($k)=>$available[$k],$selected),$out);}
    $online=$app->one('SELECT COUNT(*) count,COALESCE(SUM(total),0) total FROM orders WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status!="cancelled"',[$tenant['id'],$from,$to]);$pos=$app->one('SELECT COUNT(*) count,COALESCE(SUM(total),0) total FROM sales WHERE tenant_id=? AND DATE(created_at) BETWEEN ? AND ? AND status NOT IN ("void","refunded")',[$tenant['id'],$from,$to]);admin_shell_start('Reportes y exportaciones',$user,$tenant,'reportes');echo '<form class="card admin-card" method="get"><div class="split">'.field('Desde','from',$from,true,'date').field('Hasta','to',$to,true,'date').'</div><button class="btn">Actualizar periodo</button></form><div class="grid grid-4" style="margin-top:20px"><article class="card stat"><div class="stat-label">Ventas web</div><div class="stat-value">'.money((float)$online['total']).'</div><small>'.(int)$online['count'].' pedidos</small></article><article class="card stat"><div class="stat-label">Ventas físicas</div><div class="stat-value">'.money((float)$pos['total']).'</div><small>'.(int)$pos['count'].' ventas</small></article><article class="card stat"><div class="stat-label">Total combinado</div><div class="stat-value">'.money((float)$online['total']+(float)$pos['total']).'</div></article></div><section class="card admin-card" style="margin-top:20px"><h2>Exportar datos por elección</h2><p class="muted">Elige el conjunto y las columnas. El archivo CSV abre directamente en Excel, Google Sheets o LibreOffice.</p><form method="get"><input type="hidden" name="from" value="'.e($from).'"><input type="hidden" name="to" value="'.e($to).'"><div class="form-group"><label>Información</label><select class="input" name="export"><option value="products">Productos</option><option value="customers">Clientes</option><option value="sales">Ventas por periodo</option><option value="items">Ventas por artículo</option><option value="inventory">Inventario valorizado</option><option value="purchases">Compras</option><option value="cxc">Cuentas por cobrar</option><option value="cxp">Cuentas por pagar</option></select></div><p><strong>Columnas:</strong> si no marcas ninguna, se exportarán todas.</p><div class="module-checks">';foreach(['sku'=>'Código','name'=>'Nombre / producto','category'=>'Categoría','supplier'=>'Proveedor','price'=>'Precio','cost'=>'Costo','stock'=>'Existencia','status'=>'Estado','date'=>'Fecha','number'=>'Documento','channel'=>'Canal','customer'=>'Cliente','payment'=>'Pago','subtotal'=>'Subtotal','tax'=>'Impuesto','total'=>'Total','quantity'=>'Cantidad','balance'=>'Saldo','due'=>'Vencimiento'] as $key=>$label)echo '<label><input type="checkbox" name="columns[]" value="'.e($key).'"> <span><strong>'.e($label).'</strong></span></label>';echo '</div><button class="btn btn-accent">Descargar CSV</button></form></section>';admin_shell_end();
