function order_status_qa(App $app,int $tenantId,int $orderId,string $status,int $userId):void
{
    if(!in_array($status,['new','confirmed','preparing','ready','sent','delivered','cancelled'],true))throw new DomainException('Estado inválido.');
    $own=!$app->db->inTransaction();if($own)$app->db->beginTransaction();
    try{
        $order=$app->one('SELECT * FROM orders WHERE id=? AND tenant_id=? FOR UPDATE',[$orderId,$tenantId]);
        if(!$order)throw new DomainException('Pedido no disponible para esta empresa.');
        if($order['status']==='cancelled'&&$status!=='cancelled')throw new DomainException('Un pedido cancelado no se puede reabrir. Crea un pedido nuevo.');
        if($order['status']==='delivered'&&$status==='cancelled')throw new DomainException('Una entrega finalizada requiere revisar la devolución con administración.');
        if($status==='cancelled'){
            inventory_restore_order_v14($app,$orderId,$userId);
            $app->exec('UPDATE delivery_jobs SET status="cancelled",updated_at=NOW() WHERE order_id=? AND tenant_id=? AND status NOT IN ("delivered","cancelled","expired")',[$orderId,$tenantId]);
        }
        if($status==='delivered'&&$order['status']!=='delivered'){
            $job=$app->one('SELECT id,assigned_driver_id,status FROM delivery_jobs WHERE order_id=? AND tenant_id=? FOR UPDATE',[$orderId,$tenantId]);
            if($job&&!in_array($job['status'],['delivered','cancelled','expired'],true)){
                $app->exec('UPDATE delivery_jobs SET status="delivered",delivered_at=NOW(),updated_at=NOW() WHERE id=?',[$job['id']]);
                if($job['assigned_driver_id'])$app->exec('UPDATE driver_profiles SET completed_deliveries=completed_deliveries+1 WHERE user_id=?',[$job['assigned_driver_id']]);
            }
        }
        $app->exec('UPDATE orders SET status=?,updated_at=NOW() WHERE id=? AND tenant_id=?',[$status,$orderId,$tenantId]);
        if($own)$app->db->commit();
    }catch(Throwable $e){if($own&&$app->db->inTransaction())$app->db->rollBack();throw $e;}
}
